<?php
require_once __DIR__.'/config.php'; require_admin();
require_once __DIR__.'/lib/terminal.php'; require_once __DIR__.'/lib/app_ui.php';
require_once __DIR__.'/lib/terminal_status.php';
require_once __DIR__.'/lib/terminal_configuration.php';
$error='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
    try {
        $action=$_POST['action']??'';
        $conn->exec('BEGIN IMMEDIATE');
        if ($action==='toggle') {
            $enabled=isset($_POST['enabled']) ? 1:0;
            if ($enabled && getenv('APP_TERMINAL_ENABLED')!=='1') { throw new AttendanceError('Zuerst APP_TERMINAL_ENABLED=1 auf dem Server setzen.'); }
            if (!$enabled && att_one($conn,'SELECT id FROM work_sessions WHERE ended_at IS NULL LIMIT 1')) { throw new AttendanceError('Zuerst offene Arbeitszeiten beenden.'); }
            if ($enabled && !attendance_enabled($conn) && att_one($conn,'SELECT id FROM zeiterfassung WHERE endzeit IS NULL LIMIT 1')) { throw new AttendanceError('Zuerst vorhandene offene Arbeitszeiten im bisherigen System beenden.'); }
            terminal_save_module_settings_locked($conn,(bool)$enabled);
        } elseif ($action==='site') {
            $name=trim((string)($_POST['name']??'')); if ($name===''||strlen($name)>100) { throw new AttendanceError('Standortnamen prüfen.',400); }
            terminal_create_site_locked($conn,$name);
        } elseif ($action==='device') {
            attendance_require_enabled($conn);
            $name=trim((string)($_POST['name']??'')); $site=(int)($_POST['site_id']??0);
            if ($name===''||strlen($name)>100||!att_one($conn,'SELECT id FROM terminal_sites WHERE id=?',[$site])) { throw new AttendanceError('Name und Standort prüfen.',400); }
            $code=bin2hex(random_bytes(24));
            att_exec($conn,'INSERT INTO terminals(site_id,name,generation,pairing_hash,pairing_expires) VALUES(?,?,?,?,?)',[$site,$name,bin2hex(random_bytes(16)),hash('sha256',$code),time()+600]);
            $_SESSION['terminal_pairing']=['id'=>(int)$conn->lastInsertId(),'code'=>$code];
        } elseif ($action==='revoke_device') {
            att_exec($conn,'UPDATE terminals SET enabled=0,generation=?,pairing_hash=NULL,pairing_expires=NULL WHERE id=?',[bin2hex(random_bytes(16)),(int)($_POST['id']??0)]);
        } elseif ($action==='credential') {
            $user=(int)($_POST['user_id']??0); $site=(int)($_POST['site_id']??0); $code=trim((string)($_POST['employee_code']??'')); $pin=(string)($_POST['pin']??''); $card=trim((string)($_POST['card']??''));
            if (!att_one($conn,'SELECT id FROM users WHERE id=?',[$user])||!att_one($conn,'SELECT id FROM terminal_sites WHERE id=?',[$site])||!preg_match('/^[a-zA-Z0-9_-]{2,32}$/D',$code)||!preg_match('/^[0-9]{8}$/D',$pin)||strlen($card)>128) { throw new AttendanceError('Person, Standort, Personalcode und achtstellige PIN prüfen.',400); }
            att_exec($conn,'INSERT INTO employee_credentials(user_id,site_id,employee_code,pin_hash,card_hash,enabled) VALUES(?,?,?,?,?,1) ON CONFLICT(user_id) DO UPDATE SET site_id=excluded.site_id,employee_code=excluded.employee_code,pin_hash=excluded.pin_hash,card_hash=excluded.card_hash,enabled=1',[$user,$site,$code,password_hash($pin,PASSWORD_DEFAULT),$card===''?null:terminal_card($card)]);
        } elseif ($action==='revoke_credential') {
            att_exec($conn,'UPDATE employee_credentials SET enabled=0 WHERE user_id=?',[(int)($_POST['user_id']??0)]);
        } else { throw new AttendanceError('Unbekannte Aktion.',400); }
        $conn->exec('COMMIT'); header('Location: terminals.php?saved=1'); exit;
    } catch (Throwable $e) { $conn->exec('ROLLBACK'); $error=$e instanceof AttendanceError ? $e->getMessage():'Änderung nicht gespeichert. Personalcode, Karte oder Name möglicherweise schon vergeben.'; }
}
$sites=$conn->query('SELECT * FROM terminal_sites ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);
$users=$conn->query('SELECT id,username FROM users ORDER BY username')->fetchAll(PDO::FETCH_ASSOC);
$devices=$conn->query('SELECT t.*,s.name AS site FROM terminals t JOIN terminal_sites s ON s.id=t.site_id ORDER BY t.id DESC')->fetchAll(PDO::FETCH_ASSOC);
$credentials=$conn->query('SELECT c.user_id,c.employee_code,c.enabled,c.card_hash,u.username,s.name AS site FROM employee_credentials c JOIN users u ON u.id=c.user_id JOIN terminal_sites s ON s.id=c.site_id')->fetchAll(PDO::FETCH_ASSOC);
$pair=$_SESSION['terminal_pairing']??null; unset($_SESSION['terminal_pairing']);
$terminalStatusNow=time();
chrono_page('Praxis-Terminals');
?>
<p class="opacity-70">Geräte koppeln, persönliche Zugänge verwalten und tatsächliche Pausen erfassen.</p>
<?php if ($error): ?><div class="alert alert-error mb-6" role="alert"><?= h($error) ?></div><?php endif; ?>
<?php if ($error==='' && isset($_GET['saved'])): ?><div class="alert alert-success mb-6">Änderung gespeichert.</div><?php endif; ?>
<?php if ($pair): ?><div class="alert alert-success mb-6"><strong>Gerät <?= h($pair['id']) ?> koppeln · zehn Minuten gültig</strong><p>Den folgenden Einmalcode am Gerätedienst eingeben. Er wird nur jetzt angezeigt.</p><code><?= h($pair['code']) ?></code></div><?php endif; ?>
<div class="card bg-base-100 shadow-xl p-6 mb-6"><h2 class="text-xl font-semibold mb-4">Optionaler Terminal-Betrieb</h2><p>Bei Aktivierung verwenden Web und Terminal dieselben Buchungen. Pausen werden tatsächlich erfasst; es erfolgt kein automatischer Mindestpausenabzug. Nachträgliche Änderungen laufen über Korrekturanträge.</p><p>Serverfreigabe: <strong><?= getenv('APP_TERMINAL_ENABLED')==='1'?'vorhanden':'aus – APP_TERMINAL_ENABLED=1 erforderlich' ?></strong></p><form method="post"><?= csrf_field() ?><input class="input input-bordered w-full" type="hidden" name="action" value="toggle"><label class="block text-sm font-semibold mt-4 mb-2"><input class="checkbox checkbox-primary" type="checkbox" name="enabled" <?= attendance_enabled($conn)?'checked':'' ?>> Modul aktivieren</label><button class="btn btn-primary">Speichern</button></form></div>
<div class="grid grid-cols-1 md:grid-cols-2 gap-6"><section class="card bg-base-100 shadow-xl p-6 mb-6"><h2 class="text-xl font-semibold mb-4">Neues Gerät</h2><form method="post"><?= csrf_field() ?><input class="input input-bordered w-full" type="hidden" name="action" value="device"><label class="block text-sm font-semibold mt-4 mb-2" for="device-name">Gerätename</label><input class="input input-bordered w-full" id="device-name" name="name" maxlength="100" placeholder="Personaleingang" required><label class="block text-sm font-semibold mt-4 mb-2" for="device-site">Standort</label><select class="select select-bordered w-full" id="device-site" name="site_id"><?php foreach($sites as $site): ?><option value="<?= h($site['id']) ?>"><?= h($site['name']) ?></option><?php endforeach; ?></select><div class="flex flex-wrap gap-3 mt-5"><button class="btn btn-primary">Einmalcode erzeugen</button></div></form><p class="opacity-70">Kopplung im lokalen Gerätedienst, niemals durch Hinterlegen eines Admin-Passworts am Terminal.</p></section>
<section class="card bg-base-100 shadow-xl p-6 mb-6"><h2 class="text-xl font-semibold mb-4">Persönlicher Terminal-Zugang</h2><form method="post"><?= csrf_field() ?><input class="input input-bordered w-full" type="hidden" name="action" value="credential"><label class="block text-sm font-semibold mt-4 mb-2" for="user_id">Beschäftigte Person</label><select class="select select-bordered w-full" id="user_id" name="user_id"><?php foreach($users as $u): ?><option value="<?= h($u['id']) ?>"><?= h($u['username']) ?></option><?php endforeach; ?></select><label class="block text-sm font-semibold mt-4 mb-2" for="credential-site">Standort</label><select class="select select-bordered w-full" id="credential-site" name="site_id"><?php foreach($sites as $site): ?><option value="<?= h($site['id']) ?>"><?= h($site['name']) ?></option><?php endforeach; ?></select><label class="block text-sm font-semibold mt-4 mb-2" for="employee_code">Personalcode</label><input class="input input-bordered w-full" id="employee_code" name="employee_code" pattern="[a-zA-Z0-9_-]{2,32}" required autocomplete="off"><label class="block text-sm font-semibold mt-4 mb-2" for="pin">Neue PIN · 8 Ziffern</label><input class="input input-bordered w-full" id="pin" name="pin" type="password" inputmode="numeric" pattern="[0-9]{8}" autocomplete="new-password" required><label class="block text-sm font-semibold mt-4 mb-2" for="card">NFC-Kennung · optional</label><input class="input input-bordered w-full" id="card" name="card" maxlength="128" autocomplete="off"><small class="block opacity-70 mt-3">Ein USB-Leser kann die Kennung hier als Tastatureingabe einlesen. Die PIN bleibt erforderlich. Speichern ersetzt den bisherigen Zugang einschließlich Karte.</small><div class="flex flex-wrap gap-3 mt-5"><button class="btn btn-primary">Zugang speichern / ersetzen</button></div></form></section></div>
<section class="card bg-base-100 shadow-xl p-6 mb-6"><h2 class="text-xl font-semibold mb-4">Geräte</h2><p class="opacity-70 mb-4">Freigabe und letzter Kontakt sind unabhängig. Kontakt gilt nach <?= TERMINAL_CONTACT_MAX_AGE ?> Sekunden als veraltet; aktueller Kontakt garantiert keine Erreichbarkeit. Stand beim Laden der Seite.</p><div class="table-responsive"><table class="table"><thead><tr><th>Gerät</th><th>Standort</th><th>Freigabe</th><th>Kontaktstatus</th><th>Letzter Kontakt</th><th></th></tr></thead><tbody><?php foreach($devices as $d): $contact=terminal_contact_status($d['last_seen']??null,$terminalStatusNow); ?><tr><td><?= h($d['name']) ?> #<?= h($d['id']) ?></td><td><?= h($d['site']) ?></td><td><?= $d['enabled']?'Freigegeben':($d['pairing_hash']&&$d['pairing_expires']>$terminalStatusNow?'Kopplung offen':'Gesperrt / abgelaufen') ?></td><td><span class="<?= in_array($contact['state'],['stale','invalid'],true)?'text-warning font-semibold':'' ?>"><?= h($contact['label']) ?></span></td><td><?= h($contact['last_seen']!==null?attendance_local($contact['last_seen']):'—') ?></td><td><form method="post"><?= csrf_field() ?><input class="input input-bordered w-full" type="hidden" name="action" value="revoke_device"><input class="input input-bordered w-full" type="hidden" name="id" value="<?= h($d['id']) ?>"><button class="btn btn-error">Sperren</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="card bg-base-100 shadow-xl p-6 mb-6"><h2 class="text-xl font-semibold mb-4">Terminal-Zugänge</h2><div class="table-responsive"><table class="table"><thead><tr><th>Person</th><th>Personalcode</th><th>Standort</th><th>Zugang</th><th></th></tr></thead><tbody><?php foreach($credentials as $c): ?><tr><td><?= h($c['username']) ?></td><td><?= h($c['employee_code']) ?></td><td><?= h($c['site']) ?></td><td><?= $c['enabled']?($c['card_hash']?'PIN + Karte':'PIN'):'Gesperrt' ?></td><td><form method="post"><?= csrf_field() ?><input class="input input-bordered w-full" type="hidden" name="action" value="revoke_credential"><input class="input input-bordered w-full" type="hidden" name="user_id" value="<?= h($c['user_id']) ?>"><button class="btn btn-error">Zugang sperren</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="card bg-base-100 shadow-xl p-6 mb-6"><h2 class="text-xl font-semibold mb-4">Standort ergänzen</h2><form method="post"><?= csrf_field() ?><input class="input input-bordered w-full" type="hidden" name="action" value="site"><label class="block text-sm font-semibold mt-4 mb-2" for="site-name">Name</label><input class="input input-bordered w-full" id="site-name" name="name" maxlength="100" required><div class="flex flex-wrap gap-3 mt-5"><button class="btn btn-primary">Standort anlegen</button></div></form></section>
<?php chrono_page_end(); ?>
